resource apim 'Microsoft.ApiManagement/service@2023-09-01-preview' = {
  name: 'apim-quotient'
  location: location
  sku: { name: 'Premium', capacity: 1 }   // Premium supports VNet injection
  identity: { type: 'SystemAssigned' }
  properties: { publisherEmail: 'platform@example.com', publisherName: 'Quotient' }
}

// Backend App Service uses a private endpoint and denies public traffic
resource site 'Microsoft.Web/sites@2023-12-01' = {
  name: 'app-quotient-internal'
  location: location
  properties: {
    publicNetworkAccess: 'Disabled'
    siteConfig: { ipSecurityRestrictionsDefaultAction: 'Deny' }
  }
}
